from ....classes_common.parents import container_or_parent
from typing import TYPE_CHECKING
import numpy as np

from ....Classes_new.scidatatool.data_1d import Data1D
from ....Classes_new.scidatatool.data_linspace import DataLinspace
from ....Classes_new.scidatatool.data_time import DataTime
from ....Functions_new.Winding.gen_phase_list import gen_name


if TYPE_CHECKING:
    from ....Classes_new.output.output import Output


def get_wave(self, output: Output | None = None) -> DataTime:
    """Return the wave generated by the Drive

    Parameters
    ----------
    self : DriveWave
        A DriveWave object
    output : Output, optional
        Output of the simulation (default: the fourth parent, Output.Simulation.Electrical.EEC.Drive)

    Returns
    -------
    wave : DataTime
        Voltage / current waveform (Nt, qs)
    """

    wave = self.wave.get_data()

    Phase = Data1D(
        name="phase",
        unit="",
        values=np.array(gen_name(wave.shape[0])),
        is_components=True,
    )
    # Ouput.Simulation.Electrical.EEC.Drive
    output = container_or_parent(self, output, "output", depth=4)
    if (
        output is not None
        and output.elec.time is not None
        and len(output.elec.time) > 1
    ):
        Time = Data1D(
            name="time", unit="s", values=output.elec.time
        )
    else:
        Nt = wave.shape[1]
        Time = DataLinspace(
            name="time",
            unit="s",
            symmetries={},
            initial=0,
            final=Nt,
            number=Nt,
            include_endpoint=False,
        )

    if self.is_current:
        return DataTime(
            name="Current", unit="A", symbol="I", axes=[Phase, Time], values=wave
        )
    else:
        return DataTime(
            name="Voltage", unit="V", symbol="U", axes=[Phase, Time], values=wave
        )
